def solve(arr):
    total = sum(arr)
    if total % 3 != 0:
        return False
    target = total // 3
    parts = 0
    running = 0
    for i, x in enumerate(arr):
        running += x
        if running == target and parts < 2 and i < len(arr) - 1:
            parts += 1
            running = 0
    return parts == 2 and running == target

